INSERT INTO films (titre, slug, description, annee, pays, langue, youtube_id, thumbnail_url, published_at, is_published, is_featured) VALUES
('La Cruche Brisée (Jésus Côte d''Ivoire)', 'la-cruche-brisee', NULL, 2026, 'Côte d''Ivoire', 'fr', 'c2rjkuiJVsQ', 'https://img.youtube.com/vi/c2rjkuiJVsQ/hqdefault.jpg', '2026-10-18T14:13:56-07:00', true, false),
('Marié par Prophétie — Épisode 16 (7SELAH)', 'marie-par-prophetie-ep16', 'Dans cet épisode 16, les certitudes vacillent et certaines questions deviennent impossibles à ignorer : peut-on aimer sincèrement quelqu''un sans avoir eu le courage de le choisir ? L''amour suffit-il pour construire un mariage heureux ? / In episode 16, certainties waver and some questions can no longer be ignored: can you sincerely love someone without having had the courage to choose them? Is love enough to build a happy marriage?', 2026, 'Cameroun', 'fr', 'dAb_KXAFF5g', 'https://img.youtube.com/vi/dAb_KXAFF5g/hqdefault.jpg', '2026-10-16T10:00:07-07:00', true, false),
('La Dette de l''Enfer (Atorishé Media Group)', 'la-dette-de-l-enfer', 'Pilote d''un thriller gospel africain : Tony, homme respecté, voit sa vie basculer quand une mystérieuse dette spirituelle liée à l''esprit Sodjê réclame son prix, tandis que son ami Jean, attiré par l''argent facile, s''enfonce dans des pratiques occultes. Un combat entre la lumière et les ténèbres. / Pilot of an African gospel thriller: Tony, a respected man, sees his life turn upside down when a mysterious spiritual debt tied to the spirit Sodjê comes to claim its price, while his friend Jean, drawn to easy money, sinks into dangerous occult practices. A battle between light and darkness.', 2026, 'Bénin', 'fr', 'xHSZ1MxaREY', 'https://img.youtube.com/vi/xHSZ1MxaREY/hqdefault.jpg', '2026-10-14T12:18:21-07:00', true, false),
('Autel contre Autel (Jésus Côte d''Ivoire)', 'autel-contre-autel', NULL, 2026, 'Côte d''Ivoire', 'fr', 'MylFAfwDy5A', 'https://img.youtube.com/vi/MylFAfwDy5A/hqdefault.jpg', '2026-10-14T04:49:47-07:00', true, false),
('Le Choix de Dieu (Atorishé Media Group)', 'le-choix-de-dieu', 'Alex prie et jeûne pendant 21 jours pour que Dieu lui donne la femme de sa vie. Un vieil homme lui annonce que la première jeune femme qui le saluera le lendemain sera celle que Dieu a choisie… mais le lendemain, tout change. Un film gospel sur la foi, l''obéissance, le mariage et les choix mystérieux de Dieu. / Alex prays and fasts for 21 days asking God to give him the woman of his life. An old man tells him that the first young woman to greet him the next day will be the one God has chosen… but the next morning, everything changes. A gospel film about faith, obedience, marriage and God''s mysterious choices.', 2026, 'Burkina Faso', 'fr', '2aqDhNZMAc4', 'https://img.youtube.com/vi/2aqDhNZMAc4/hqdefault.jpg', '2026-10-10T03:17:46-07:00', true, false),
('Marié par Prophétie — Épisode 15 (7SELAH)', 'marie-par-prophetie-ep15', 'Dans cet épisode 15, Paul décide enfin de poser les questions qu''il n''avait jamais osé poser. Entre amour, mariage chrétien, prophétie, pression familiale, volonté de Dieu et discernement, certaines décisions pourraient tout changer : peut-on encore reconstruire son mariage quand les certitudes s''effondrent ? / In episode 15, Paul finally decides to ask the questions he never dared to ask. Between love, Christian marriage, prophecy, family pressure, God''s will and discernment, some decisions could change everything: can a marriage still be rebuilt when certainties collapse?', 2026, 'Cameroun', 'fr', '1eivQ2iKYuQ', 'https://img.youtube.com/vi/1eivQ2iKYuQ/hqdefault.jpg', '2026-10-09T09:45:06-07:00', true, false),
('Derrière la Chaire ? (Jésus Côte d''Ivoire)', 'derriere-la-chaire', 'Quand un adultère juge un autre adultère. Un film chrétien sur le jugement, l''hypocrisie et ce qui se cache derrière la chaire. / When one adulterer judges another. A Christian film about judgment, hypocrisy and what hides behind the pulpit.', 2026, 'Côte d''Ivoire', 'fr', 'iqXSqTwPUqg', 'https://img.youtube.com/vi/iqXSqTwPUqg/hqdefault.jpg', '2026-10-09T09:23:57-07:00', true, false),
('Le Faible (Atorishé Media Group)', 'le-faible', 'Daniel refuse de répondre à la violence par la violence : face aux provocations de son épouse Sarah, il choisit la prière. Elle commence à l''appeler « le faible »… Un film gospel mêlant drame familial, mariage, foi, prière et combat spirituel. / Daniel refuses to answer violence with violence: facing the provocations of his wife Sarah, he chooses prayer. She starts calling him “the weak one”… A gospel film mixing family drama, marriage, faith, prayer and spiritual warfare.', 2026, 'Bénin', 'fr', '7jNcvQjXby4', 'https://img.youtube.com/vi/7jNcvQjXby4/hqdefault.jpg', '2026-10-08T09:08:41-07:00', true, false);
